css:
.fx-frev .pg{width:min(980px,100%);margin:0 auto;padding:3em 1.25em 6em;display:grid;gap:3.5em}
.fx-frev .pg section{display:grid;gap:.9em}
.fx-frev .pg .k{font-size:.75em;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--accent)}
.fx-frev .pg h2{font-size:clamp(1.6em,3.4vw,2.2em)}
.fx-frev .pg p{opacity:.7;max-width:60ch}
.fx-frev .pg .fx-art{aspect-ratio:21/9;border-radius:var(--radius);margin-top:.4em}
.fx-frev{background:var(--primary)}
.fx-frev .mn{position:relative;z-index:1;background:var(--surface);min-height:130vh;box-shadow:0 30px 60px -10px rgba(0,0,0,.35);border-radius:0 0 calc(var(--radius)*2) calc(var(--radius)*2)}
.fx-frev .hint{padding:4em 1.25em 0;text-align:center;font-size:.8em;font-weight:700;letter-spacing:.16em;text-transform:uppercase;opacity:.55}
.fx-frev .ft{position:fixed;left:0;right:0;bottom:0;z-index:0;background:var(--primary);color:var(--on-primary);padding:3.4em max(5vw,1.25em) 1.6em}
.fx-frev .fi{width:min(1080px,100%);margin:0 auto;display:grid;gap:2.6em}
.fx-frev .top{display:grid;grid-template-columns:1.2fr 2fr;gap:3em}
.fx-frev .brand b{display:block;font:600 2em var(--font-heading);margin-bottom:.4em}.fx-frev .brand p{opacity:.78;max-width:30ch}
.fx-frev .cols{display:grid;grid-template-columns:repeat(3,1fr);gap:1.4em}
.fx-frev h3{font:700 .72em var(--font-body);letter-spacing:.14em;text-transform:uppercase;opacity:.65;margin-bottom:1em}
.fx-frev ul{list-style:none;margin:0;padding:0;display:grid;gap:.6em}
.fx-frev .ft a{color:inherit;text-decoration:none;opacity:.85;background:linear-gradient(currentColor,currentColor) 0 100%/0 1px no-repeat;transition:background-size calc(.3s/var(--speed)),opacity .2s;padding-bottom:.1em}
.fx-frev .ft a:hover,.fx-frev .ft a:focus-visible{opacity:1;background-size:100% 1px}
.fx-frev .ft a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}
.fx-frev .bot{display:flex;justify-content:space-between;gap:1em;flex-wrap:wrap;padding-top:1.4em;border-top:1px solid color-mix(in srgb,var(--on-primary) 25%,transparent);font-size:.85em;opacity:.8}
.fx-frev .bot nav{display:flex;gap:1.4em}
.fx-frev.flat .ft{position:static}.fx-frev.flat .mn{margin-bottom:0!important;box-shadow:none;border-radius:0;min-height:0}
@media(max-width:760px){.fx-frev .top{grid-template-columns:1fr;gap:1.6em}.fx-frev .cols{grid-template-columns:repeat(2,1fr)}.fx-frev .ft{padding-top:2.4em}}
@media(prefers-reduced-motion:reduce){.fx-frev .ft{position:static}.fx-frev .mn{margin-bottom:0!important;box-shadow:none;min-height:0;border-radius:0}.fx-frev .ft a{transition:none}}
/* touch: :hover mirrored as .is-tap */
.fx-frev .ft a.is-tap{opacity:1;background-size:100% 1px}

js:
(function(){var r=document.querySelector('.fx-frev');if(!r)return;var f=r.querySelector('.ft'),m=r.querySelector('.mn');
function s(){r.classList.remove('flat');var h=f.offsetHeight;if(h>innerHeight*.8){r.classList.add('flat');m.style.marginBottom=''}else m.style.marginBottom=h+'px'}
s();addEventListener('resize',s);if(window.ResizeObserver)new ResizeObserver(s).observe(f)})();
/* fx-touch */
(function(){if(window.__fxTap)return;window.__fxTap=1;var cur=[];function clr(){cur.forEach(function(e){e.classList.remove('is-tap')});cur=[]}
document.addEventListener('pointerdown',function(e){if(e.pointerType!=='touch')return;clr();var n=e.target.closest&&e.target.closest('.fx');if(!n)return;for(var el=e.target;el&&el!==n.parentNode;el=el.parentNode){if(el.classList){el.classList.add('is-tap');cur.push(el)}}},{passive:true});
document.addEventListener('pointerup',function(){setTimeout(clr,1400)},{passive:true})})();
